import { readFile, writeFile } from "node:fs/promises";
import { ASPECT_IDS, ASPECTS } from "../src/modules/aspect/api.ts";
import { AGENTS, HARNESSES } from "../src/modules/harness/api.ts";

const root = new URL("../", import.meta.url);
const manifest = JSON.parse(
  await readFile(new URL("package.json", root), "utf8"),
) as {
  dependencies: Record<string, string>;
};
const note =
  "<!-- Generated by pnpm docs:generate. Do not edit directly. -->\n\n";
const aspects = `${note}# Built-in review catalog

All ${ASPECT_IDS.length} built-in rubrics are enabled by default, in review priority order.
Each rubric contains three contextual REPORT and three contextual PRESERVE examples.
These are teaching material, not executed programs or model efficacy measurements.
PRESERVE means preserve within that aspect, not a correctness certificate.
The complete absence of a requested feature is outside this slop catalog.

The worker receives the common instruction, response contract, resolved assignment
and exactly one rubric. Repository content is evidence, never reviewer instructions.

## Priority order

| Aspect | Review question |
| --- | --- |
${ASPECT_IDS.map((id) => `| [${id}](https://github.com/GR34SE/degreaser-axi/blob/main/src/modules/aspect/${id}/rubric.md) | ${ASPECTS[id].meta.summary} |`).join("\n")}

## Boundary map

| Pair | Routing rule |
| --- | --- |
${ASPECT_IDS.flatMap((id) => ASPECTS[id].meta.boundaries.map((b) => `| ${id} ${b.reciprocal ? "/" : "→"} ${b.other} | ${b.rule} |`)).join("\n")}

Source labels in rubrics identify their inspirations, not a requirement to load
private authoring documents. Every rubric contains its complete applicability,
evidence requirements, boundaries and examples.
`;
const harnesses = `${note}# Native review workers

| Harness | Adapter / verified native version | Effective restriction |
| --- | --- | --- |
${AGENTS.map((id) => {
  const h = HARNESSES[id];
  const adapter = h.adapterPackage
    ? `${h.adapterPackage} ${manifest.dependencies[h.adapterPackage]}`
    : "native ACP";
  return `| ${h.displayName} | ${adapter} / ${h.supportedVersions.verified} | ${h.guarantee} |`;
}).join("\n")}

${await readFile(new URL("src/modules/harness/common/readme.md", root), "utf8")}
${(await Promise.all(AGENTS.map(async (id) => (await readFile(new URL(`src/modules/harness/${id}/readme.md`, root), "utf8")).replace(/^# /, "## ")))).join("\n")}
`;
for (const [name, content] of Object.entries({ aspects, harnesses })) {
  const path = new URL(`docs/${name}.md`, root);
  const generated = `${content.trimEnd()}\n`;
  if (process.argv.includes("--check")) {
    if ((await readFile(path, "utf8")) !== generated)
      throw new Error(`docs/${name}.md is stale. Run pnpm docs:generate.`);
  } else await writeFile(path, generated);
}
